<template><view class="manual-picker"><view class="book-grid"><button v-for="i in 4" :key="i" hover-class="none" :class="['book-tile','glass',`book-${i}`,{locked:!available(i),selected:selected===`inspire${i}`}]" :disabled="!available(i)" @click="$emit('select','inspire'+i)"><view class="book-tile-top"><view class="book-cover"><text class="cover-series">inspire</text><text class="cover-number">{{ i }}</text></view><Icon v-if="!available(i)" name="lock" /></view><view class="book-tile-bottom"><view><h2>Inspire {{ i }}</h2><Bi :zh="available(i)?`${count(i)} 个课次`:'暂未开放'" :fr="available(i)?`${count(i)} leçons`:'Bientôt'" small /></view><Icon :name="available(i)?'arrow':'lock'" /></view></button><button v-if="bookCounts?.fos1" hover-class="none" :class="['book-tile','glass','book-fos',{selected:selected==='fos1'}]" @click="$emit('select','fos1')"><view class="book-tile-top"><view class="book-cover"><text class="cover-series">FOS</text><text class="cover-number">1</text></view></view><view class="book-tile-bottom"><view><h2>FOS 1</h2><Bi :zh="`${bookCounts.fos1} 个课次`" :fr="`${bookCounts.fos1} leçons`" small/></view><Icon name="arrow"/></view></button><button v-if="showImported" hover-class="none" :class="['book-tile','glass','book-imported',{selected:selected==='imported'}]" @click="$emit('select','imported')"><view class="book-tile-top"><view class="book-cover"><text class="cover-series">mes mots</text><Icon name="cards"/></view></view><view class="book-tile-bottom"><view><h2>导入本</h2><Bi :zh="`${imported} 个课次`" :fr="`${imported} leçons`" small/></view><Icon name="arrow"/></view></button><button v-if="showImported" hover-class="none" :class="['book-tile','glass','book-imported',{selected:selected==='special'}]" @click="$emit('select','special')"><view class="book-tile-top"><view class="book-cover"><text class="cover-series">à part</text><Icon name="cards"/></view></view><view class="book-tile-bottom"><view><h2>特殊导入</h2><Bi :zh="`${special} 个课次`" :fr="`${special} leçons`" small/></view><Icon name="arrow"/></view></button></view></view></template>
<script setup>
import Bi from './Bi.vue';import Icon from './Icon.vue';const props=defineProps({selected:String,lessons:Number,bookCounts:Object,imported:Number,special:Number,showImported:{type:Boolean,default:false}});const count=i=>props.bookCounts?.['inspire'+i]??(i===1?props.lessons||0:0);const available=i=>props.bookCounts?count(i)>0:i===1;defineEmits(['select']);
</script>
<style scoped>.book-fos .book-cover{background:linear-gradient(145deg,#dce9f1,#acc9db);color:#41677e}.book-imported .book-cover{background:linear-gradient(145deg,#e0ece8,#c3dcd4);color:#487566}.book-imported .book-cover>.icon{width:35px;height:35px;margin-top:14px}</style>
